// Build Trend Stats v2 — filters garbage sessions before aggregating.
// Garbage = duration_min < 10 OR (sport in cycling/running and distance_km is null/<=0)
const wrapped = $json;
const all = Array.isArray(wrapped.sessions) ? wrapped.sessions : [];
const normSport = t => { const x = (t||'').toLowerCase(); if (x.includes('swim')) return 'Swim'; if (x.includes('run')) return 'Run'; if (x.includes('ride')||x.includes('bike')||x.includes('cycl')||x.includes('virtual')) return 'Ride'; return t; };
const sport = normSport($('Get Activity Details').item.json.type);
const sessions = all.filter(s => {
  if (normSport(s.sport) !== sport) return false;
  if (!s.duration_min || s.duration_min < 10) return false;
  // For distance-based sports, drop null/zero distance records (incomplete uploads)
  if (['Ride','Run','Swim','Walk','Hike'].includes(sport)) {
    if (!s.distance_km || s.distance_km <= 0) return false;
  }
  return true;
});

if (sessions.length === 0) {
  return { json: { trendSummary: '(no comparable ' + sport + ' sessions in last 30d)' } };
}

const numAvg = (arr, k) => {
  const vals = arr.map(s => parseFloat(s[k])).filter(v => !isNaN(v) && v !== 0);
  return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
};
const round1 = n => n == null ? null : Math.round(n * 10) / 10;

const stats = {
  count: sessions.length,
  avg_duration: numAvg(sessions, 'duration_min'),
  avg_distance: numAvg(sessions, 'distance_km'),
  avg_tss: numAvg(sessions, 'tss'),
  avg_hr: numAvg(sessions, 'avg_hr'),
  avg_power: numAvg(sessions, 'avg_power'),
  avg_decoupling: numAvg(sessions, 'decoupling'),
  avg_ef: numAvg(sessions, 'efficiency_factor'),
};
const longest = sessions.reduce((m, s) => (s.duration_min || 0) > (m?.duration_min || 0) ? s : m, null);
const grades = sessions.filter(s => s.grade).map(s => s.grade);
const gradeBreakdown = ['A','B','C','F'].map(g => g + ':' + grades.filter(x => x === g).length).join(' ');

const lines = [];
lines.push(sport + ' sessions (last 30d, valid only): ' + stats.count);
const avgParts = [];
if (stats.avg_duration) avgParts.push(Math.round(stats.avg_duration) + 'min');
if (stats.avg_distance) avgParts.push(round1(stats.avg_distance) + 'km');
if (stats.avg_tss) avgParts.push('TSS ' + Math.round(stats.avg_tss));
if (stats.avg_hr) avgParts.push('HR ' + Math.round(stats.avg_hr) + 'bpm');
if (avgParts.length) lines.push('Avg: ' + avgParts.join(' · '));
if (stats.avg_power) lines.push('Avg power: ' + Math.round(stats.avg_power) + 'W');
if (stats.avg_decoupling) lines.push('Avg decoupling: ' + round1(stats.avg_decoupling));
if (stats.avg_ef) lines.push('Avg efficiency factor: ' + round1(stats.avg_ef));
if (longest && longest.duration_min) lines.push('Longest: ' + longest.duration_min + 'min on ' + longest.date);
if (grades.length) lines.push('Grade distribution (A/B/C/F): ' + gradeBreakdown);

return { json: { trendSummary: lines.join('\n') } };

// Build Sport Metrics v2 — handles ICU streams single-object response.
const normSport = t => { const x = (t||'').toLowerCase(); if (x.includes('swim')) return 'Swim'; if (x.includes('run')) return 'Run'; if (x.includes('ride')||x.includes('bike')||x.includes('cycl')||x.includes('virtual')) return 'Ride'; return t; };
const sport = normSport($('Get Activity Details').item.json.type);
const a = $('Get Activity Details').item.json;
const trendSummary = $('Build Trend Stats').item.json.trendSummary || '';

// Streams: ICU returns either an array of {type, data} OR a single
// {type, data, allNull, ...} when one type was requested. Normalize.
let torqueData = null;
try {
  const resp = $input.item.json;
  const body = resp && resp.body !== undefined ? resp.body : resp;
  let candidates = [];
  if (Array.isArray(body)) candidates = body;
  else if (body && typeof body === 'object' && body.type) candidates = [body];
  else if (Array.isArray(body?.data) && body.data[0]?.type) candidates = body.data;
  const torque = candidates.find(s => s && s.type === 'torque');
  if (torque && Array.isArray(torque.data) && !torque.allNull) {
    torqueData = torque.data.filter(v => typeof v === 'number' && v > 0);
  }
} catch (e) {}

const lines = [];

if (sport === 'Run') {
  const cadenceSpm = a.average_cadence ? Math.round(a.average_cadence * 2) : null;
  const stride = a.average_stride;
  if (cadenceSpm) lines.push('Cadence: ' + cadenceSpm + ' spm (total stride rate)');
  if (stride) lines.push('Stride length: ' + stride.toFixed(2) + ' m');
  if (a.average_speed) {
    const paceSec = 1000 / a.average_speed;
    const min = Math.floor(paceSec / 60);
    const sec = Math.round(paceSec % 60);
    lines.push('Pace: ' + min + ':' + String(sec).padStart(2, '0') + '/km');
  }
  lines.push('Targets: cadence 170-180 spm at endurance pace; stride length 0.85-1.10 m at Z2');
  lines.push('Note: Running Dynamics (GCT, vertical oscillation, vertical ratio) NOT available — COROS PACE 3 wrist-only does not capture these. Stride/cadence-based form coaching only.');
} else if (sport === 'Swim') {
  const sr = a.average_cadence;
  const dps = a.average_stride;
  const poolLen = a.pool_length;
  const lengths = a.lengths;
  const movingSec = a.moving_time;
  if (sr) lines.push('Stroke rate (SR): ' + sr.toFixed(1) + ' spm');
  if (dps) lines.push('Distance per stroke (DPS): ' + dps.toFixed(2) + ' m');
  if (poolLen && lengths) lines.push('Pool: ' + poolLen + 'm × ' + lengths + ' lengths');
  if (movingSec && lengths && sr) {
    const secsPerLength = movingSec / lengths;
    const strokesPerLength = sr * secsPerLength / 60;
    const swolf = Math.round(secsPerLength + strokesPerLength);
    lines.push('SWOLF: ~' + swolf + ' (' + Math.round(secsPerLength) + 's + ' + Math.round(strokesPerLength) + ' strokes per length)');
  }
  lines.push('Targets: SWOLF <38 strong, 38-45 moderate, >45 work needed. DPS 1.4-1.8m freestyle. Lower SR with high DPS = efficient.');
} else if (sport === 'Ride') {
  if (typeof a.icu_cadence_z2 === 'number') lines.push('Cadence Z2 time: ' + a.icu_cadence_z2 + 'min in efficient cadence band (out of ' + Math.round(a.moving_time/60) + 'min total)');
  if (typeof a.polarization_index === 'number') lines.push('Polarization index: ' + a.polarization_index.toFixed(2) + ' (lower = more monotone effort, higher = polarized Z1+Z4)');
  if (typeof a.icu_joules_above_ftp === 'number' && a.icu_joules_above_ftp > 0) {
    lines.push('Anaerobic work: ' + Math.round(a.icu_joules_above_ftp / 1000) + ' kJ above FTP');
  }
  if (torqueData && torqueData.length > 100) {
    const mean = torqueData.reduce((s, v) => s + v, 0) / torqueData.length;
    const variance = torqueData.reduce((s, v) => s + Math.pow(v - mean, 2), 0) / torqueData.length;
    const std = Math.sqrt(variance);
    const cv = mean > 0 ? std / mean : 0;
    lines.push('Torque variability (CV): ' + cv.toFixed(2) + ' across ' + torqueData.length + ' pedaling samples (avg torque ' + Math.round(mean) + 'Nm; <0.30 smooth, 0.30-0.50 moderate, >0.50 choppy)');
  }
  lines.push('Note: L/R balance and pedaling smoothness % NOT available — SRAM Apex AXS is a single-sided crank-arm meter (only measures non-drive side).');
}

if (lines.length === 0) lines.push('(no sport-specific form metrics for ' + sport + ')');

return { json: { trendSummary, sportMetrics: lines.join('\n') } };

// Readiness line from Intervals.icu wellness (Zepp band). Passes trend/sport metrics through.
const prev = $('Build Sport Metrics').item.json;
let readinessLine = '(no wellness data)';
try {
  const resp = $input.item.json;
  const days = Array.isArray(resp.body) ? resp.body : [];
  const valid = days.filter(d => d && /^\d{4}-\d{2}-\d{2}$/.test(d.id || '')).sort((a, b) => (a.id < b.id ? -1 : 1));
  if (valid.length) {
    const day = valid[valid.length - 1]; // day of the session
    const base = valid.slice(0, -1);     // prior days = baseline
    const avg = (arr, f) => { const v = arr.map(d => d[f]).filter(x => x != null); return v.length ? v.reduce((s, x) => s + x, 0) / v.length : null; };
    const parts = [];
    if (day.sleepSecs != null) parts.push('Sleep ' + Math.floor(day.sleepSecs / 3600) + 'h' + String(Math.round((day.sleepSecs % 3600) / 60)).padStart(2, '0') + (day.sleepScore != null ? ' (score ' + Math.round(day.sleepScore) + ')' : ''));
    const hrvBase = avg(base, 'hrv');
    if (day.hrv != null) parts.push('HRV ' + Math.round(day.hrv) + (hrvBase != null ? ' (7d avg ' + Math.round(hrvBase) + ')' : ''));
    const rhrBase = avg(base, 'restingHR');
    if (day.restingHR != null) parts.push('RHR ' + Math.round(day.restingHR) + (rhrBase != null ? ' (7d avg ' + Math.round(rhrBase) + ')' : ''));
    if (parts.length) readinessLine = parts.join(' · ');
  }
} catch (e) {}
return { json: { ...prev, readinessLine } };

// Detected fitness test -> rewrite FTP/CSS/threshold across athlete free-text fields.
const t = JSON.parse($json.detected_test);
const a = $('Loop Over Users').item.json;
const fields = {
  fitness_profile: a['Fitness Profile'] || '',
  goal: a['Goal'] || '',
  constraints: a['Constraints'] || '',
  health_status: a['Health Status'] || '',
};
const specs = {
  ftp: { rx: /(FTP:?\s*(?:today\s*)?)(\d{2,3})(\s*W)?/g, val: (String(t.value).match(/\d{2,3}/) || [])[0], unit: 'W', label: 'FTP' },
  css: { rx: /(CSS:?\s*(?:today\s*)?)(\d:\d{2})(\/100m)?/g, val: (String(t.value).match(/\d:\d{2}/) || [])[0], unit: '/100m', label: 'Swim CSS' },
  run_threshold: { rx: /((?:Run\s+)?[Tt]hreshold:?\s*)(\d:\d{2})(\/km)/g, val: (String(t.value).match(/\d:\d{2}/) || [])[0], unit: '/km', label: 'Run threshold' },
};
const spec = specs[t.kind];
let oldVal = null;
if (spec && spec.val) {
  for (const k of Object.keys(fields)) {
    fields[k] = fields[k].replace(spec.rx, (m, p1, p2, p3) => {
      if (oldVal === null) oldVal = p2;
      return p1 + spec.val + (p3 || '');
    });
  }
  fields.health_status = fields.health_status.replace(/Last updated \d{4}-\d{2}-\d{2}/, 'Last updated ' + DateTime.now().toFormat('yyyy-MM-dd'));
}
const note = spec && spec.val
  ? (oldVal !== null && oldVal !== spec.val
      ? '📈 ' + spec.label + ' updated ' + oldVal + ' → ' + spec.val + spec.unit + (t.evidence ? ' (' + t.evidence + ')' : '')
      : oldVal !== null
        ? '📈 ' + spec.label + ' test confirmed current value ' + spec.val + spec.unit + (t.evidence ? ' (' + t.evidence + ')' : '')
        : '📈 ' + spec.label + ' test detected (' + spec.val + spec.unit + ') but no matching profile entry — update manually.')
  : '📈 Unrecognized test payload: ' + $json.detected_test;
return { json: { note, body: fields } };

